import Phaser from "phaser";
import colisionesDataRaw from "../assets/fondo1_colisiones_rpg_hibrido.json";
import puntosExclamacion from "../exclamaciones";
import type {
  OpenUiDetail,
  CollisionArea,
  RawColisionesData,
} from "../types";

const PLAYER_SPEED = 130;
const PLAYER_FRAME_WIDTH = 61;
const PLAYER_FRAME_HEIGHT = 92;
const HOUSE_DOOR_OFFSET_Y = 14;
const LOGICAL_MAP_WIDTH = 1024;
const LOGICAL_MAP_HEIGHT = 512;

/**
 * Spritesheet: assets-removebg-preview.png (677x369 px, 11 cols x 4 filas)
 * Fila 0 – walk-down  : frames  0 – 10
 * Fila 1 – walk-up    : frames 11 – 21
 * Fila 2 – walk-left  : frames 22 – 32
 * Fila 3 – walk-right : frames 33 – 43
 */
const ANIMATION_ROWS = {
  down: { start: 0, end: 10, idle: 0 },
  up: { start: 11, end: 21, idle: 11 },
  left: { start: 22, end: 32, idle: 22 },
  right: { start: 33, end: 43, idle: 33 },
} as const;

type FacingDirection = "down" | "up" | "left" | "right";

type TriggerZone = Phaser.GameObjects.Zone & {
  body: Phaser.Physics.Arcade.StaticBody;
};

export default class Scene extends Phaser.Scene {
  private player!: Phaser.Physics.Arcade.Sprite;
  private mapScaleX = 1;
  private mapScaleY = 1;
  private facing: FacingDirection = "down";
  private cursors!: Phaser.Types.Input.Keyboard.CursorKeys;
  private wasd!: {
    up: Phaser.Input.Keyboard.Key;
    down: Phaser.Input.Keyboard.Key;
    left: Phaser.Input.Keyboard.Key;
    right: Phaser.Input.Keyboard.Key;
  };
  private keyInteractE!: Phaser.Input.Keyboard.Key;
  private keyInteractEnter!: Phaser.Input.Keyboard.Key;
  private triggerZones!: Phaser.GameObjects.Group;
  private activeTriggerName: string | null = null;
  private collisionGroup!: Phaser.Physics.Arcade.StaticGroup;

  constructor() {
    super("GameScene");
  }

  preload(): void {
    this.load.image("map", require("../assets/fondo1.png"));

    this.load.spritesheet(
      "player",
      require("../assets/assets-removebg-preview.png"),
      {
        frameWidth: PLAYER_FRAME_WIDTH,
        frameHeight: PLAYER_FRAME_HEIGHT,
      },
    );
  }

  create(): void {
    const mapImage = this.add.image(0, 0, "map").setOrigin(0, 0);
    const mapWidth = mapImage.width;
    const mapHeight = mapImage.height;
    this.mapScaleX = mapWidth / LOGICAL_MAP_WIDTH;
    this.mapScaleY = mapHeight / LOGICAL_MAP_HEIGHT;

    const spawnPoint = this.getPlayerSpawnPoint();

    this.player = this.physics.add.sprite(
      spawnPoint.x,
      spawnPoint.y,
      "player",
      ANIMATION_ROWS.down.idle,
    );
    this.player.setCollideWorldBounds(true);
    const playerBody = this.player.body as Phaser.Physics.Arcade.Body;
    playerBody.setSize(20, 28);
    playerBody.setOffset(18, 52);

    this.cameras.main.startFollow(this.player, true, 0.09, 0.09);
    this.cameras.main.setBounds(0, 0, mapWidth, mapHeight);
    this.physics.world.setBounds(0, 0, mapWidth, mapHeight);

    this.createAnimations();
    this.createCollisionsFromTilemap();
    this.createInteractionTriggers();

    const keyboard = this.input.keyboard;
    if (!keyboard) {
      return;
    }

    this.cursors = keyboard.createCursorKeys();
    this.wasd = keyboard.addKeys({
      up: Phaser.Input.Keyboard.KeyCodes.W,
      down: Phaser.Input.Keyboard.KeyCodes.S,
      left: Phaser.Input.Keyboard.KeyCodes.A,
      right: Phaser.Input.Keyboard.KeyCodes.D,
    }) as {
      up: Phaser.Input.Keyboard.Key;
      down: Phaser.Input.Keyboard.Key;
      left: Phaser.Input.Keyboard.Key;
      right: Phaser.Input.Keyboard.Key;
    };

    this.keyInteractE = keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.E);
    this.keyInteractEnter = keyboard.addKey(
      Phaser.Input.Keyboard.KeyCodes.ENTER,
    );
  }

  update(): void {
    if (!this.player?.body || !this.cursors || !this.wasd) {
      return;
    }

    this.handleMovement();
    this.checkTriggerOverlap();

    if (
      this.activeTriggerName &&
      (Phaser.Input.Keyboard.JustDown(this.keyInteractE) ||
        Phaser.Input.Keyboard.JustDown(this.keyInteractEnter))
    ) {
      const detail: OpenUiDetail = { section: this.activeTriggerName };
      window.dispatchEvent(
        new CustomEvent<OpenUiDetail>("open-ui", { detail }),
      );
    }
  }

  private createAnimations(): void {
    this.anims.create({
      key: "walk-down",
      frames: this.anims.generateFrameNumbers("player", {
        start: ANIMATION_ROWS.down.start,
        end: ANIMATION_ROWS.down.end,
      }),
      frameRate: 10,
      repeat: -1,
    });
    this.anims.create({
      key: "walk-left",
      frames: this.anims.generateFrameNumbers("player", {
        start: ANIMATION_ROWS.left.start,
        end: ANIMATION_ROWS.left.end,
      }),
      frameRate: 10,
      repeat: -1,
    });
    this.anims.create({
      key: "walk-right",
      frames: this.anims.generateFrameNumbers("player", {
        start: ANIMATION_ROWS.right.start,
        end: ANIMATION_ROWS.right.end,
      }),
      frameRate: 10,
      repeat: -1,
    });
    this.anims.create({
      key: "walk-up",
      frames: this.anims.generateFrameNumbers("player", {
        start: ANIMATION_ROWS.up.start,
        end: ANIMATION_ROWS.up.end,
      }),
      frameRate: 10,
      repeat: -1,
    });
  }

  private createCollisionsFromTilemap(): void {
    const colisionesData = colisionesDataRaw as RawColisionesData;
    const collisionAreas: CollisionArea[] = (colisionesData.colisiones || []).map(
      (obj) => ({
        x: obj.x,
        y: obj.y,
        width: obj.w,
        height: obj.h,
        type: obj.tipo,
      }),
    );

    this.collisionGroup = this.physics.add.staticGroup();

    if (collisionAreas.length > 0) {
      collisionAreas.forEach((obj) => {
        if (
          obj.x !== undefined &&
          obj.y !== undefined &&
          obj.width &&
          obj.height &&
          obj.width > 0 &&
          obj.height > 0
        ) {
          // El JSON de colisiones esta dibujado sobre fondo1.png, se usa en coordenadas reales.
          const scaledX = obj.x;
          const scaledY = obj.y;
          const scaledWidth = obj.width;
          const scaledHeight = obj.height;

          const zone = this.add.zone(
            scaledX + scaledWidth / 2,
            scaledY + scaledHeight / 2,
            scaledWidth,
            scaledHeight,
          );

          this.physics.add.existing(zone, true);

          // Agregar propiedad con el tipo de colisión para debugging
          if (obj.type) {
            zone.setData("collisionType", obj.type);
          }

          this.collisionGroup.add(zone);
        }
      });
    }

    this.physics.add.collider(this.player, this.collisionGroup);
  }

  private getPlayerSpawnPoint(): { x: number; y: number } {
    const homeMarker = puntosExclamacion.find((point) =>
      point.name.includes("Casa"),
    );
    if (homeMarker) {
      return {
        x: homeMarker.x * this.mapScaleX,
        y: (homeMarker.y + HOUSE_DOOR_OFFSET_Y) * this.mapScaleY,
      };
    }

    return {
      x: 512 * this.mapScaleX,
      y: 348 * this.mapScaleY,
    };
  }

  private createInteractionTriggers(): void {
    this.triggerZones = this.add.group();

    puntosExclamacion.forEach((point) => {
      const zone = this.add
        .zone(
          point.x * this.mapScaleX,
          point.y * this.mapScaleY,
          28 * this.mapScaleX,
          28 * this.mapScaleY,
        )
        .setOrigin(0.5, 0.5) as TriggerZone;
      this.physics.add.existing(zone, true);
      zone.setData("section", point.name);
      this.triggerZones.add(zone);
    });
  }

  private checkTriggerOverlap(): void {
    this.activeTriggerName = null;
    this.physics.overlap(
      this.player,
      this.triggerZones,
      (_player, zoneObject) => {
        const zone = zoneObject as Phaser.GameObjects.Zone;
        const section = zone.getData("section") as string | undefined;
        if (section) {
          this.activeTriggerName = section;
        }
      },
      undefined,
      this,
    );
  }

  private handleMovement(): void {
    const body = this.player.body as Phaser.Physics.Arcade.Body;
    body.setVelocity(0, 0);

    const left = this.cursors.left?.isDown || this.wasd.left.isDown;
    const right = this.cursors.right?.isDown || this.wasd.right.isDown;
    const up = this.cursors.up?.isDown || this.wasd.up.isDown;
    const down = this.cursors.down?.isDown || this.wasd.down.isDown;

    if (left) {
      body.setVelocityX(-PLAYER_SPEED);
      this.facing = "left";
      this.player.anims.play("walk-left", true);
    } else if (right) {
      body.setVelocityX(PLAYER_SPEED);
      this.facing = "right";
      this.player.anims.play("walk-right", true);
    }

    if (up) {
      body.setVelocityY(-PLAYER_SPEED);
      if (!left && !right) {
        this.facing = "up";
        this.player.anims.play("walk-up", true);
      }
    } else if (down) {
      body.setVelocityY(PLAYER_SPEED);
      if (!left && !right) {
        this.facing = "down";
        this.player.anims.play("walk-down", true);
      }
    }

    body.velocity.normalize().scale(PLAYER_SPEED);

    if (!left && !right && !up && !down) {
      this.player.anims.stop();
      this.player.setFrame(ANIMATION_ROWS[this.facing].idle);
    }
  }
}

import Phaser from "phaser";
import colisionesDataRaw from "../assets/fondo1_colisiones_rpg_hibrido.json";
import puntosExclamacion from "../exclamaciones";
import type {
  OpenUiDetail,
  CollisionArea,
  RawColisionesData,
} from "../types";

const PLAYER_SPEED = 130;
const PLAYER_FRAME_WIDTH = 61;
const PLAYER_FRAME_HEIGHT = 92;
const HOUSE_DOOR_OFFSET_Y = 14;
const LOGICAL_MAP_WIDTH = 1024;
const LOGICAL_MAP_HEIGHT = 512;

/**
 * Spritesheet: assets-removebg-preview.png (677x369 px, 11 cols x 4 filas)
 * Fila 0 – walk-down  : frames  0 – 10
 * Fila 1 – walk-up    : frames 11 – 21
 * Fila 2 – walk-left  : frames 22 – 32
 * Fila 3 – walk-right : frames 33 – 43
 */
const ANIMATION_ROWS = {
  down: { start: 0, end: 10, idle: 0 },
  up: { start: 11, end: 21, idle: 11 },
  left: { start: 22, end: 32, idle: 22 },
  right: { start: 33, end: 43, idle: 33 },
} as const;

type FacingDirection = "down" | "up" | "left" | "right";

type TriggerZone = Phaser.GameObjects.Zone & {
  body: Phaser.Physics.Arcade.StaticBody;
};

export default class Scene extends Phaser.Scene {
  private player!: Phaser.Physics.Arcade.Sprite;
  private mapScaleX = 1;
  private mapScaleY = 1;
  private facing: FacingDirection = "down";
  private cursors!: Phaser.Types.Input.Keyboard.CursorKeys;
  private wasd!: {
    up: Phaser.Input.Keyboard.Key;
    down: Phaser.Input.Keyboard.Key;
    left: Phaser.Input.Keyboard.Key;
    right: Phaser.Input.Keyboard.Key;
  };
  private keyInteractE!: Phaser.Input.Keyboard.Key;
  private keyInteractEnter!: Phaser.Input.Keyboard.Key;
  private triggerZones!: Phaser.GameObjects.Group;
  private activeTriggerName: string | null = null;
  private collisionGroup!: Phaser.Physics.Arcade.StaticGroup;

  constructor() {
    super("GameScene");
  }

  preload(): void {
    this.load.image("map", require("../assets/fondo1.png"));

    this.load.spritesheet(
      "player",
      require("../assets/assets-removebg-preview.png"),
      {
        frameWidth: PLAYER_FRAME_WIDTH,
        frameHeight: PLAYER_FRAME_HEIGHT,
      },
    );
  }

  create(): void {
    const mapImage = this.add.image(0, 0, "map").setOrigin(0, 0);
    const mapWidth = mapImage.width;
    const mapHeight = mapImage.height;
    this.mapScaleX = mapWidth / LOGICAL_MAP_WIDTH;
    this.mapScaleY = mapHeight / LOGICAL_MAP_HEIGHT;

    const spawnPoint = this.getPlayerSpawnPoint();

    this.player = this.physics.add.sprite(
      spawnPoint.x,
      spawnPoint.y,
      "player",
      ANIMATION_ROWS.down.idle,
    );
    this.player.setCollideWorldBounds(true);
    const playerBody = this.player.body as Phaser.Physics.Arcade.Body;
    playerBody.setSize(20, 28);
    playerBody.setOffset(18, 52);

    this.cameras.main.startFollow(this.player, true, 0.09, 0.09);
    this.cameras.main.setBounds(0, 0, mapWidth, mapHeight);
    this.physics.world.setBounds(0, 0, mapWidth, mapHeight);

    this.createAnimations();
    this.createCollisionsFromTilemap();
    this.createInteractionTriggers();

    const keyboard = this.input.keyboard;
    if (!keyboard) {
      return;
    }

    this.cursors = keyboard.createCursorKeys();
    this.wasd = keyboard.addKeys({
      up: Phaser.Input.Keyboard.KeyCodes.W,
      down: Phaser.Input.Keyboard.KeyCodes.S,
      left: Phaser.Input.Keyboard.KeyCodes.A,
      right: Phaser.Input.Keyboard.KeyCodes.D,
    }) as {
      up: Phaser.Input.Keyboard.Key;
      down: Phaser.Input.Keyboard.Key;
      left: Phaser.Input.Keyboard.Key;
      right: Phaser.Input.Keyboard.Key;
    };

    this.keyInteractE = keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.E);
    this.keyInteractEnter = keyboard.addKey(
      Phaser.Input.Keyboard.KeyCodes.ENTER,
    );
  }

  update(): void {
    if (!this.player?.body || !this.cursors || !this.wasd) {
      return;
    }

    this.handleMovement();
    this.checkTriggerOverlap();

    if (
      this.activeTriggerName &&
      (Phaser.Input.Keyboard.JustDown(this.keyInteractE) ||
        Phaser.Input.Keyboard.JustDown(this.keyInteractEnter))
    ) {
      const detail: OpenUiDetail = { section: this.activeTriggerName };
      window.dispatchEvent(
        new CustomEvent<OpenUiDetail>("open-ui", { detail }),
      );
    }
  }

  private createAnimations(): void {
    this.anims.create({
      key: "walk-down",
      frames: this.anims.generateFrameNumbers("player", {
        start: ANIMATION_ROWS.down.start,
        end: ANIMATION_ROWS.down.end,
      }),
      frameRate: 10,
      repeat: -1,
    });
    this.anims.create({
      key: "walk-left",
      frames: this.anims.generateFrameNumbers("player", {
        start: ANIMATION_ROWS.left.start,
        end: ANIMATION_ROWS.left.end,
      }),
      frameRate: 10,
      repeat: -1,
    });
    this.anims.create({
      key: "walk-right",
      frames: this.anims.generateFrameNumbers("player", {
        start: ANIMATION_ROWS.right.start,
        end: ANIMATION_ROWS.right.end,
      }),
      frameRate: 10,
      repeat: -1,
    });
    this.anims.create({
      key: "walk-up",
      frames: this.anims.generateFrameNumbers("player", {
        start: ANIMATION_ROWS.up.start,
        end: ANIMATION_ROWS.up.end,
      }),
      frameRate: 10,
      repeat: -1,
    });
  }

  private createCollisionsFromTilemap(): void {
    const colisionesData = colisionesDataRaw as RawColisionesData;
    const collisionAreas: CollisionArea[] = (colisionesData.colisiones || []).map(
      (obj) => ({
        x: obj.x,
        y: obj.y,
        width: obj.w,
        height: obj.h,
        type: obj.tipo,
      }),
    );

    this.collisionGroup = this.physics.add.staticGroup();

    if (collisionAreas.length > 0) {
      collisionAreas.forEach((obj) => {
        if (
          obj.x !== undefined &&
          obj.y !== undefined &&
          obj.width &&
          obj.height &&
          obj.width > 0 &&
          obj.height > 0
        ) {
          // El JSON de colisiones esta dibujado sobre fondo1.png, se usa en coordenadas reales.
          const scaledX = obj.x;
          const scaledY = obj.y;
          const scaledWidth = obj.width;
          const scaledHeight = obj.height;

          const zone = this.add.zone(
            scaledX + scaledWidth / 2,
            scaledY + scaledHeight / 2,
            scaledWidth,
            scaledHeight,
          );

          this.physics.add.existing(zone, true);

          // Agregar propiedad con el tipo de colisión para debugging
          if (obj.type) {
            zone.setData("collisionType", obj.type);
          }

          this.collisionGroup.add(zone);
        }
      });
    }

    this.physics.add.collider(this.player, this.collisionGroup);
  }

  private getPlayerSpawnPoint(): { x: number; y: number } {
    const homeMarker = puntosExclamacion.find((point) =>
      point.name.includes("Casa"),
    );
    if (homeMarker) {
      return {
        x: homeMarker.x * this.mapScaleX,
        y: (homeMarker.y + HOUSE_DOOR_OFFSET_Y) * this.mapScaleY,
      };
    }

    return {
      x: 512 * this.mapScaleX,
      y: 348 * this.mapScaleY,
    };
  }

  private createInteractionTriggers(): void {
    this.triggerZones = this.add.group();

    puntosExclamacion.forEach((point) => {
      const zone = this.add
        .zone(
          point.x * this.mapScaleX,
          point.y * this.mapScaleY,
          28 * this.mapScaleX,
          28 * this.mapScaleY,
        )
        .setOrigin(0.5, 0.5) as TriggerZone;
      this.physics.add.existing(zone, true);
      zone.setData("section", point.name);
      this.triggerZones.add(zone);
    });
  }

  private checkTriggerOverlap(): void {
    this.activeTriggerName = null;
    this.physics.overlap(
      this.player,
      this.triggerZones,
      (_player, zoneObject) => {
        const zone = zoneObject as Phaser.GameObjects.Zone;
        const section = zone.getData("section") as string | undefined;
        if (section) {
          this.activeTriggerName = section;
        }
      },
      undefined,
      this,
    );
  }

  private handleMovement(): void {
    const body = this.player.body as Phaser.Physics.Arcade.Body;

    const left = this.cursors.left?.isDown || this.wasd.left.isDown;
    const right = this.cursors.right?.isDown || this.wasd.right.isDown;
    const up = this.cursors.up?.isDown || this.wasd.up.isDown;
    const down = this.cursors.down?.isDown || this.wasd.down.isDown;

    let dirX = 0;
    let dirY = 0;

    if (left && !right) {
      dirX = -1;
    } else if (right && !left) {
      dirX = 1;
    }

    if (up && !down) {
      dirY = -1;
    } else if (down && !up) {
      dirY = 1;
    }

    if (dirX !== 0 || dirY !== 0) {
      if (dirX !== 0 && dirY !== 0) {
        // Mantener velocidad constante en diagonal.
        const diagonalFactor = Math.SQRT1_2;
        body.setVelocity(
          dirX * PLAYER_SPEED * diagonalFactor,
          dirY * PLAYER_SPEED * diagonalFactor,
        );
      } else {
        body.setVelocity(dirX * PLAYER_SPEED, dirY * PLAYER_SPEED);
      }

      if (dirY < 0 && dirX === 0) {
        this.facing = "up";
        this.player.anims.play("walk-up", true);
      } else if (dirY > 0 && dirX === 0) {
        this.facing = "down";
        this.player.anims.play("walk-down", true);
      } else if (dirX < 0) {
        this.facing = "left";
        this.player.anims.play("walk-left", true);
      } else if (dirX > 0) {
        this.facing = "right";
        this.player.anims.play("walk-right", true);
      }
      return;
    }

    body.setVelocity(0, 0);
    this.player.anims.stop();
    this.player.setFrame(ANIMATION_ROWS[this.facing].idle);
  }
}

/**
 * Presets de temas predefinidos
 */

import type { Theme } from "./theme";

/**
 * Tema retro pixel por defecto (estado actual del CSS)
 */
export const retroTheme: Theme = {
  name: "retro",
  colors: {
    bgPrimary: "#10151d",
    bgSecondary: "#162131",
    bgTertiary: "#0e131b",
    frameOuter: "#0a0f15",
    frameInner: "#3b4e66",
    panelBg: "#f1e5b8",
    panelBorder: "#2d2116",
    panelBorder2: "#7b6140",
    textMain: "#17130f",
    textLight: "#f3f2e4",
    accent: "#2c7a6b",
    accent2: "#18443a",
    danger: "#b0462a",
  },
  spacing: {
    xs: "4px",
    sm: "8px",
