    panelBorder2: "#4a4a4a",
    textMain: "#e8e8e8",
    textLight: "#f3f2e4",
    accent: "#3d9680",
    accent2: "#1f5550",
    danger: "#d05030",
  },
  spacing: {
    xs: "4px",
    sm: "8px",
