    lg: "16px",
    xl: "24px",
  },
  fontSizes: {
    xs: "7px",
    sm: "8px",
    base: "9px",
    lg: "10px",
    xl: "12px",
    xxl: "13px",
  },
};

export const THEMES = {
  retro: retroTheme,
  "retro-dark": retroDarkTheme,
} as const;

export type ThemeName = keyof typeof THEMES;

/** * Presets de temas predefinidos */
import type { Theme } from "./theme";
/** * Tema retro pixel por defecto (estado actual del CSS) */ export const retroTheme: Theme = { name: "retro", colors: { bgPrimary: "#10151d", bgSecondary: "#162131", bgTertiary: "#0e131b", frameOuter: "#0a0f15", frameInner: "#3b4e66", panelBg: "#f1e5b8", panelBorder: "#2d2116", panelBorder2: "#7b6140", textMain: "#17130f", textLight: "#f3f2e4", accent: "#2c7a6b", accent2: "#18443a", danger: "#b0462a", }, spacing: { xs: "4px", sm: "8px", md: "12px", lg: "16px", xl: "24px", }, fontSizes: { xs: "7px", sm: "8px", base: "9px", lg: "10px", xl: "12px", xxl: "13px", }, };
