/** * Tema claro y limpio */ export const lightTheme: Theme = { name: "light", colors: { bgPrimary: "#f5f5f5", bgSecondary: "#e8e8e8", bgTertiary: "#f0f0f0", frameOuter: "#d0d0d0", frameInner: "#c0c0c0", panelBg: "#ffffff", panelBorder: "#333333", panelBorder2: "#666666", textMain: "#1a1a1a", textLight: "#555555", accent: "#2c7a6b", accent2: "#18443a", danger: "#cc3333", }, spacing: { xs: "4px", sm: "8px", md: "12px", lg: "16px", xl: "24px", }, fontSizes: { xs: "7px", sm: "8px", base: "9px", lg: "10px", xl: "12px", xxl: "13px", }, };
/** * Tema verde matriz (Matrix/Cyberpunk) */ export const matrixTheme: Theme = { name: "matrix", colors: { bgPrimary: "#000000", bgSecondary: "#0a0a0a", bgTertiary: "#050505", frameOuter: "#000000", frameInner: "#003300", panelBg: "#001100", panelBorder: "#003300", panelBorder2: "#006600", textMain: "#00ff00", textLight: "#00ff00", accent: "#00ff00", accent2: "#00cc00", danger: "#ff0000", }, spacing: { xs: "4px", sm: "8px", md: "12px", lg: "16px", xl: "24px", }, fontSizes: { xs: "7px", sm: "8px", base: "9px", lg: "10px", xl: "12px", xxl: "13px", }, };
export const THEMES = { retro: retroTheme, "retro-dark": retroDarkTheme, neon: neonTheme, light: lightTheme, matrix: matrixTheme, } as const;
export type ThemeName = keyof typeof THEMES;

.theme-debug-info {
  position: fixed;
  bottom: 70px;
  left: 16px;
  display: flex;
  gap: 8px;
  align-items: center;
  flex-wrap: wrap;
  z-index: 100;
  max-width: 200px;
}

.theme-debug-colors {
  display: flex;
  gap: 4px;
}

.theme-debug-swatch {
  width: 20px;
  height: 20px;
  border: 2px solid #000;
  border-radius: 2px;
}

@import url("https://fonts.googleapis.com/css2?family=Press+Start+2P&display=swap");

:root {
  /* Layout */
  --layout-max-width: 1520px;

  /* Backgrounds */
  --bg-1: #10151d;
  --bg-2: #162131;
  --bg-3: #0e131b;

  /* Frames */
  --frame-outer: #0a0f15;
  --frame-inner: #3b4e66;

  /* Panels */
  --panel-bg: #f1e5b8;
  --panel-border: #2d2116;
  --panel-border-2: #7b6140;

  /* Text */
  --text-main: #17130f;
  --text-light: #f3f2e4;

  /* Accents */
  --accent: #2c7a6b;
  --accent-2: #18443a;
  --danger: #b0462a;

  /* Spacing */
  --spacing-xs: 4px;
  --spacing-sm: 8px;
  --spacing-md: 12px;
  --spacing-lg: 16px;
  --spacing-xl: 24px;

  /* Font Sizes */
  --font-xs: 7px;
  --font-sm: 8px;
  --font-base: 9px;
  --font-lg: 10px;
  --font-xl: 12px;
  --font-xxl: 13px;
}

* {
  box-sizing: border-box;
  image-rendering: pixelated;
}

html,
body,
#root {
  min-height: 100%;
}

body {
  margin: 0;
  font-family: "Press Start 2P", monospace;
  color: var(--text-main);
  background:
    linear-gradient(0deg, rgba(0, 0, 0, 0.22), rgba(0, 0, 0, 0.22)),
    repeating-linear-gradient(
      90deg,
      rgba(255, 255, 255, 0.04) 0 2px,
      transparent 2px 8px
    ),
    linear-gradient(180deg, var(--bg-2), var(--bg-1));
}

.app-shell {
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 12px;
  min-height: 100vh;
  padding: 16px;
}

.game-frame {
  width: min(var(--layout-max-width), 96vw);
  margin: 0;
  position: relative;
  border: 4px solid var(--frame-outer);
  box-shadow:
    0 0 0 4px var(--frame-inner),
    0 0 0 8px var(--frame-outer),
    0 12px 0 #06090d;
  background: #0e131b;
}

.game-canvas {
  width: 100%;
  aspect-ratio: 2 / 1;
}

.game-canvas canvas {
  display: block;
  width: 100% !important;
  height: 100% !important;
  image-rendering: pixelated;
}

.pixel-hud {
  position: absolute;
  left: 12px;
  bottom: 12px;
  padding: 10px 12px;
  font-size: 9px;
  line-height: 1.5;
  color: #f3f2e4;
  background: #1a2330;
  border: 3px solid #05080d;
  box-shadow:
    0 0 0 3px #4f6075,
    0 6px 0 #0c141d;
}

.poi-map {
  position: absolute;
  top: 10px;
  right: 10px;
  width: min(280px, 44vw);
  padding: 8px;
  background: rgba(14, 19, 27, 0.9);
  border: 3px solid #06101a;
  box-shadow: 0 0 0 3px #4f6075;
}

.poi-map-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
  margin-bottom: 8px;
}

.poi-map-title {
  margin: 0;
  font-size: 8px;
  color: #ece9d2;
}

.poi-map-toggle {
  font-family: inherit;
  font-size: 7px;
  padding: 5px 7px;
  color: #f7f0d8;
  background: #283a4f;
  border: 2px solid #0d1a2a;
  box-shadow: 0 2px 0 #0d1a2a;
  cursor: pointer;
}

.poi-map.is-minimized {
  width: auto;
  min-width: 130px;
}

.poi-map-canvas {
  position: relative;
  width: 100%;
  aspect-ratio: 2760 / 1504;
  background:
    radial-gradient(circle at 30% 55%, rgba(53, 136, 110, 0.38), transparent 60%),
    radial-gradient(circle at 67% 40%, rgba(206, 176, 98, 0.34), transparent 55%),
    #203549;
  border: 2px solid #63758a;
  overflow: hidden;
}

.poi-map-dot {
  position: absolute;
  transform: translate(-50%, -86%);
  min-width: 48px;
  min-height: 18px;
  padding: 3px 6px;
  font-family: inherit;
  font-size: 6px;
  color: #1f2932;
  background: #f6ecc3;
  border: 2px solid #11151b;
  box-shadow: 0 0 0 2px rgba(149, 168, 190, 0.65);
  text-transform: uppercase;
  cursor: pointer;
}

.poi-map-dot::after {
  content: "";
  position: absolute;
  left: calc(50% - 1px);
  top: 100%;
  width: 2px;
  height: 14px;
  background: #11151b;
}

.poi-map-dot::before {
  content: "";
  position: absolute;
  left: calc(50% - 4px);
  top: calc(100% + 12px);
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #3b4e66;
  border: 1px solid #11151b;
}

.poi-map-dot.is-active {
  background: #f4b441;
  box-shadow: 0 0 0 2px #e8b35a;
}

.poi-map-dot:disabled {
  cursor: not-allowed;
  opacity: 0.75;
}

.travel-overlay {
  position: fixed;
  inset: 0;
  z-index: 2100;
  display: grid;
  place-items: center;
  background: rgba(6, 10, 18, 0.88);
}

.travel-overlay-content {
  width: min(920px, 92vw);
  padding: 18px;
  background: #121b29;
  border: 4px solid #0a121d;
  box-shadow:
    0 0 0 4px #3a4d65,
    0 0 0 8px #0a121d;
}

.travel-overlay-content p {
  margin: 0 0 14px;
  font-size: 10px;
  color: #f6f1d8;
}

.travel-road {
  position: relative;
  overflow: hidden;
  height: 170px;
  border: 3px solid #081019;
  background:
    repeating-linear-gradient(
      90deg,
      rgba(255, 255, 255, 0.16) 0 24px,
      transparent 24px 44px
    ) center 128px / 100% 6px no-repeat,
    linear-gradient(180deg, #263c57, #101621);
}

.travel-bus {
  position: absolute;
  left: -340px;
  bottom: -20px;
  height: min(240px, 56vw);
  width: auto;
  max-width: none;
  image-rendering: pixelated;
  animation: travel-bus-run 1.8s linear infinite;
}

@keyframes travel-bus-run {
  from {
    transform: translateX(0);
  }
  to {
    transform: translateX(calc(100vw + 560px));
  }
}

@media (max-width: 768px) {
  .travel-bus {
    height: min(160px, 48vw);
  }
}

.pixel-modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.6);
  display: grid;
  place-items: center;
  padding: 16px;
}

.pixel-modal {
  width: min(760px, 100%);
  max-height: min(86vh, 700px);
  overflow: auto;
  padding: 18px;
  background: var(--panel-bg);
  border: 4px solid var(--panel-border);
  box-shadow:
    0 0 0 4px var(--panel-border-2),
    0 0 0 8px var(--panel-border),
    0 12px 0 #433423;
}

.pixel-modal-content {
  overflow-y: auto;
  max-height: calc(86vh - 140px);
}

.pixel-modal-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  margin-bottom: 14px;
  padding-bottom: 10px;
  border-bottom: 3px solid #8f7650;
}

.pixel-panel {
  padding: 12px;
  background: rgba(14, 19, 27, 0.95);
  border: 3px solid #0a0f15;
  box-shadow: 0 0 0 3px #3b4e66;
}

.pixel-card {
  padding: 12px;
  background: #f1e5b8;
  border: 3px solid #2d2116;
  box-shadow: 0 4px 0 #7b6140;
}

.pixel-text {
  margin: 0;
  font-family: inherit;
}

.pixel-text--body {
  font-size: 10px;
  line-height: 1.6;
  color: var(--text-main);
}

.pixel-text--caption {
  font-size: 8px;
  line-height: 1.5;
  color: var(--text-main);
}

.pixel-text--title {
  font-size: 12px;
  font-weight: bold;
  text-transform: uppercase;
  margin-bottom: 8px;
  color: var(--text-main);
}

.theme-switcher {
  position: fixed;
  bottom: 16px;
  left: 16px;
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  z-index: 100;
}

.theme-switcher-btn {
  font-size: 8px;
  padding: 6px 8px;
  background: rgba(14, 19, 27, 0.9);
  border: 2px solid var(--frame-inner);
  color: var(--text-light);
  cursor: pointer;
}

.theme-switcher-btn:hover {
  background: var(--frame-inner);
}

.pixel-modal-header h2 {
  margin: 0;
  font-size: 13px;
  text-transform: uppercase;
}

.pixel-btn {
  font-family: inherit;
  font-size: 9px;
  padding: 8px 10px;
  background: var(--danger);
  color: #fff7e4;
  border: 3px solid #5d1f12;
  box-shadow: 0 4px 0 #39140b;
  cursor: pointer;
}

.pixel-btn:active {
  transform: translateY(2px);
  box-shadow: 0 2px 0 #39140b;
}

.typewriter-text {
  min-height: 66px;
  margin: 0 0 14px;
  font-size: 10px;
  line-height: 1.7;
}

.pixel-list,
.link-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 8px;
}

.pixel-list li,
.link-list li {
  padding: 10px;
  font-size: 9px;
  line-height: 1.6;
  background: #fff6d8;
  border: 3px solid #8a724d;
  box-shadow: 0 4px 0 #5b4b31;
}

.skill-grid {
  display: grid;
  gap: 10px;
  grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
}

.skill-card {
  display: grid;
  gap: 8px;
  justify-items: center;
  align-content: center;
  min-height: 88px;
  font-size: 9px;
  text-align: center;
  background: #eef5dd;
  border: 3px solid var(--accent-2);
  box-shadow: 0 4px 0 var(--accent-2);
}

.skill-icon {
  display: inline-block;
  min-width: 34px;
  padding: 8px 6px;
  text-align: center;
  background: var(--accent);
  color: #f4fefb;
  border: 2px solid var(--accent-2);
}

.link-list a {
  color: #173c9f;
  text-decoration: none;
}

.link-list a:hover {
  text-decoration: underline;
}

@media (max-width: 768px) {
  .app-shell {
    padding: 10px;
  }

  .poi-map {
    width: min(210px, 58vw);
    right: 6px;
    top: 6px;
  }

  .poi-map-dot {
    font-size: 6px;
    min-width: 38px;
    padding: 3px 4px;
  }

  .pixel-hud {
    font-size: 8px;
    left: 8px;
    bottom: 8px;
  }

  .pixel-modal {
    padding: 12px;
  }

  .pixel-modal-header h2 {
    font-size: 11px;
  }
}

.theme-debug-info {
  position: fixed;
  bottom: 70px;
  left: 16px;
  display: flex;
  gap: 8px;
  align-items: center;
  flex-wrap: wrap;
  z-index: 100;
  max-width: 200px;
}

.theme-debug-colors {
  display: flex;
  gap: 4px;
}

.theme-debug-swatch {
  width: 20px;
  height: 20px;
  border: 2px solid #000;
  border-radius: 2px;
}

