.pixel-modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.6);
  display: grid;
  place-items: center;
  padding: 16px;
}

.pixel-modal {
  width: min(760px, 100%);
  max-height: min(86vh, 700px);
  overflow: auto;
  padding: 18px;
  background: var(--panel-bg);
  border: 4px solid var(--panel-border);
  box-shadow:
    0 0 0 4px var(--panel-border-2),
    0 0 0 8px var(--panel-border),
    0 12px 0 #433423;
}

.pixel-modal-content {
  overflow-y: auto;
  max-height: calc(86vh - 140px);
}

.pixel-modal-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  margin-bottom: 14px;
  padding-bottom: 10px;
  border-bottom: 3px solid #8f7650;
}

.pixel-panel {
  padding: 12px;
  background: rgba(14, 19, 27, 0.95);
  border: 3px solid #0a0f15;
  box-shadow: 0 0 0 3px #3b4e66;
}

.pixel-card {
  padding: 12px;
  background: #f1e5b8;
  border: 3px solid #2d2116;
  box-shadow: 0 4px 0 #7b6140;
}

.pixel-text {
  margin: 0;
  font-family: inherit;
}

.pixel-text--body {
  font-size: 10px;
  line-height: 1.6;
  color: var(--text-main);
}

.pixel-text--caption {
  font-size: 8px;
  line-height: 1.5;
  color: var(--text-main);
}

.pixel-text--title {
  font-size: 12px;
  font-weight: bold;
  text-transform: uppercase;
  margin-bottom: 8px;
  color: var(--text-main);
}

.theme-switcher {
  position: fixed;
  bottom: 16px;
  left: 16px;
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  z-index: 100;
}

.theme-switcher-btn {
  font-size: 8px;
  padding: 6px 8px;
  background: rgba(14, 19, 27, 0.9);
  border: 2px solid var(--frame-inner);
  color: var(--text-light);
  cursor: pointer;
}

.theme-switcher-btn:hover {
  background: var(--frame-inner);
}

.pixel-modal-header h2 {
  margin: 0;
  font-size: 13px;
  text-transform: uppercase;
}

.pixel-btn {
  font-family: inherit;
  font-size: 9px;
  padding: 8px 10px;
  background: var(--danger);
  color: #fff7e4;
  border: 3px solid #5d1f12;
  box-shadow: 0 4px 0 #39140b;
  cursor: pointer;
}

.pixel-btn:active {
  transform: translateY(2px);
  box-shadow: 0 2px 0 #39140b;
}

.typewriter-text {
  min-height: 66px;
  margin: 0 0 14px;
  font-size: 10px;
  line-height: 1.7;
}

.pixel-list,
.link-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 8px;
}

.pixel-list li,
.link-list li {
  padding: 10px;
  font-size: 9px;
  line-height: 1.6;
  background: #fff6d8;
  border: 3px solid #8a724d;
  box-shadow: 0 4px 0 #5b4b31;
}

.skill-grid {
  display: grid;
  gap: 10px;
  grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
}

.skill-card {
  display: grid;
  gap: 8px;
  justify-items: center;
  align-content: center;
  min-height: 88px;
  font-size: 9px;
  text-align: center;
  background: #eef5dd;
  border: 3px solid var(--accent-2);
  box-shadow: 0 4px 0 var(--accent-2);
}

.skill-icon {
  display: inline-block;
  min-width: 34px;
  padding: 8px 6px;
  text-align: center;
  background: var(--accent);
  color: #f4fefb;
  border: 2px solid var(--accent-2);
}

.link-list a {
  color: #173c9f;
  text-decoration: none;
}

.link-list a:hover {
  text-decoration: underline;
}

@media (max-width: 768px) {
  .app-shell {
    padding: 10px;
  }

  .poi-map {
    width: min(210px, 58vw);
    right: 6px;
    top: 6px;
  }

  .poi-map-dot {
    font-size: 6px;
    min-width: 38px;
    padding: 3px 4px;
  }

  .pixel-hud {
    font-size: 8px;
    left: 8px;
    bottom: 8px;
  }

  .pixel-modal {
    padding: 12px;
  }

  .pixel-modal-header h2 {
    font-size: 11px;
  }
}
